using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using TravelPlanner.Domain.Entities;

namespace TravelPlanner.Infrastructure.Persistence;

// Conventions: ids are generated by the domain (ValueGeneratedNever), money is numeric, enums are stored as text,
// date-only values are PostgreSQL "date", timestamps are "timestamp with time zone" in UTC.

internal sealed class DestinationConfiguration : IEntityTypeConfiguration<Destination>
{
    public void Configure(EntityTypeBuilder<Destination> b)
    {
        b.ToTable("destinations");
        b.HasKey(x => x.Id);
        b.Property(x => x.Id).ValueGeneratedNever();
        b.Property(x => x.Code).HasMaxLength(64).IsRequired();
        b.HasIndex(x => x.Code).IsUnique();
        b.Property(x => x.City).HasMaxLength(128).IsRequired();
        b.Property(x => x.Country).HasMaxLength(128).IsRequired();
        b.Property(x => x.CountryCode).HasMaxLength(2).IsFixedLength().IsRequired();
        b.Property(x => x.Region).HasMaxLength(64).IsRequired();
        b.Property(x => x.Description).HasMaxLength(2000);
        b.Property(x => x.TaxiBaseFare).HasPrecision(10, 2);
        b.Property(x => x.TaxiPerKm).HasPrecision(10, 2);
        b.Property(x => x.TaxiTariffCurrency).HasMaxLength(3);
        b.Property(x => x.TaxiTariffSource).HasMaxLength(300);
        b.Ignore(x => x.HasTaxiTariff);
        b.Property(x => x.Translations).AsJsonb().IsRequired();
        b.HasIndex(x => new { x.IsActive, x.Popularity });

        b.HasMany(x => x.Airports).WithOne(a => a.Destination).HasForeignKey(a => a.DestinationId).OnDelete(DeleteBehavior.SetNull);
        b.HasMany(x => x.TransportLinks).WithOne().HasForeignKey(l => l.DestinationId).OnDelete(DeleteBehavior.Cascade);
    }
}

internal sealed class AirportConfiguration : IEntityTypeConfiguration<Airport>
{
    public void Configure(EntityTypeBuilder<Airport> b)
    {
        b.ToTable("airports");
        b.HasKey(x => x.Id);
        b.Property(x => x.Id).ValueGeneratedNever();
        b.Property(x => x.IataCode).HasMaxLength(3).IsFixedLength().IsRequired();
        b.HasIndex(x => x.IataCode).IsUnique();
        b.Property(x => x.Name).HasMaxLength(200).IsRequired();
        b.Property(x => x.City).HasMaxLength(128).IsRequired();
        b.Property(x => x.CountryCode).HasMaxLength(2).IsFixedLength().IsRequired();
        b.Property(x => x.OfficialWebsiteUrl).HasMaxLength(500);
        b.Property(x => x.CityCode).HasMaxLength(3).IsFixedLength();
        b.Property(x => x.Country).HasMaxLength(128);
        b.Property(x => x.Continent).HasMaxLength(32);
        b.HasIndex(x => x.CityCode);
        b.Property(x => x.Translations).AsJsonb().IsRequired();
        b.HasIndex(x => x.IsDepartureOption);
    }
}

internal sealed class DestinationTransportLinkConfiguration : IEntityTypeConfiguration<DestinationTransportLink>
{
    public void Configure(EntityTypeBuilder<DestinationTransportLink> b)
    {
        b.ToTable("destination_transport_links");
        b.HasKey(x => x.Id);
        b.Property(x => x.Id).ValueGeneratedNever();
        b.Property(x => x.Kind).HasConversion<string>().HasMaxLength(32);
        b.Property(x => x.Name).HasMaxLength(200).IsRequired();
        b.Property(x => x.Url).HasMaxLength(500).IsRequired();
        b.Property(x => x.Phone).HasMaxLength(50);
        b.Property(x => x.Notes).HasMaxLength(1000);
        b.Property(x => x.NameTranslations).AsJsonb().IsRequired();
        b.HasIndex(x => new { x.DestinationId, x.Url }).IsUnique();
    }
}

internal sealed class TripSearchConfiguration : IEntityTypeConfiguration<TripSearch>
{
    public void Configure(EntityTypeBuilder<TripSearch> b)
    {
        b.ToTable("trip_searches");
        b.HasKey(x => x.Id);
        b.Property(x => x.Id).ValueGeneratedNever();
        b.Property(x => x.OriginAirportIata).HasMaxLength(3).IsFixedLength().IsRequired();
        b.Property(x => x.BudgetAmount).HasPrecision(12, 2);
        b.Property(x => x.BudgetCurrency).HasMaxLength(3).IsFixedLength().IsRequired();
        b.Property(x => x.DestinationMode).HasConversion<string>().HasMaxLength(16);
        b.Property(x => x.DataMode).HasConversion<string>().HasMaxLength(16);
        b.Property(x => x.Language).HasMaxLength(5).IsRequired().HasDefaultValue("en");
        b.Property(x => x.Status).HasConversion<string>().HasMaxLength(32);
        b.Property(x => x.ProgressMessage).HasMaxLength(300).IsRequired();
        b.Property(x => x.ErrorMessage).HasMaxLength(1000);
        b.Property(x => x.Warnings);
        b.Property(x => x.Continents);
        b.Property(x => x.FoundFlightsJson).HasColumnType("jsonb").IsRequired().HasDefaultValueSql("'[]'::jsonb");
        b.Ignore(x => x.Nights);
        b.Ignore(x => x.IsFinished);

        b.OwnsOne(x => x.Preferences, p =>
        {
            p.ToJson("preferences");
            p.Property(x => x.PreferredDepartureTime).HasConversion<string>();
        });

        b.HasMany(x => x.SelectedDestinations).WithOne().HasForeignKey(x => x.TripSearchId).OnDelete(DeleteBehavior.Cascade);
        b.HasMany(x => x.Plans).WithOne(p => p.TripSearch).HasForeignKey(p => p.TripSearchId).OnDelete(DeleteBehavior.Cascade);

        b.HasIndex(x => x.Status);
        b.HasIndex(x => x.CreatedAtUtc);
        b.ToTable(t =>
        {
            t.HasCheckConstraint("ck_trip_searches_duration", "\"DurationDays\" BETWEEN 2 AND 30");
            t.HasCheckConstraint("ck_trip_searches_travelers", "\"Travelers\" BETWEEN 1 AND 9");
            t.HasCheckConstraint("ck_trip_searches_budget", "\"BudgetAmount\" > 0");
            t.HasCheckConstraint("ck_trip_searches_window", "\"LatestReturn\" > \"EarliestDeparture\"");
        });
    }
}

internal sealed class TripSearchDestinationConfiguration : IEntityTypeConfiguration<TripSearchDestination>
{
    public void Configure(EntityTypeBuilder<TripSearchDestination> b)
    {
        b.ToTable("trip_search_destinations");
        b.HasKey(x => new { x.TripSearchId, x.DestinationId });
        b.HasOne(x => x.Destination).WithMany().HasForeignKey(x => x.DestinationId).OnDelete(DeleteBehavior.Restrict);
    }
}

internal sealed class TripPlanConfiguration : IEntityTypeConfiguration<TripPlan>
{
    public void Configure(EntityTypeBuilder<TripPlan> b)
    {
        b.ToTable("trip_plans");
        b.HasKey(x => x.Id);
        b.Property(x => x.Id).ValueGeneratedNever();
        b.Property(x => x.Score).HasPrecision(7, 2);
        b.Property(x => x.ScoreBreakdownJson).HasColumnType("jsonb").IsRequired();
        b.Property(x => x.Currency).HasMaxLength(3).IsFixedLength().IsRequired();
        b.Property(x => x.BudgetAmount).HasPrecision(12, 2);
        b.Property(x => x.TotalEstimatedCost).HasPrecision(12, 2);
        b.Property(x => x.RemainingBudget).HasPrecision(12, 2);
        b.Property(x => x.BudgetFit).HasConversion<string>().HasMaxLength(32);
        b.Ignore(x => x.Nights);

        b.HasOne(x => x.Destination).WithMany().HasForeignKey(x => x.DestinationId).OnDelete(DeleteBehavior.Restrict);
        b.HasMany(x => x.Items).WithOne().HasForeignKey(i => i.TripPlanId).OnDelete(DeleteBehavior.Cascade);
        b.HasIndex(x => new { x.TripSearchId, x.Rank }).IsUnique();
        b.ToTable(t => t.HasCheckConstraint("ck_trip_plans_dates", "\"ReturnDate\" > \"DepartureDate\""));
    }
}

internal sealed class TripPlanItemConfiguration : IEntityTypeConfiguration<TripPlanItem>
{
    public void Configure(EntityTypeBuilder<TripPlanItem> b)
    {
        b.ToTable("trip_plan_items");
        b.HasKey(x => x.Id);
        b.Property(x => x.Id).ValueGeneratedNever();
        b.Property(x => x.Type).HasConversion<string>().HasMaxLength(32);
        b.Property(x => x.Direction).HasConversion<string>().HasMaxLength(32);
        b.Property(x => x.Verification).HasConversion<string>().HasMaxLength(32);
        b.Property(x => x.Category).HasMaxLength(64).IsRequired();
        b.Property(x => x.Title).HasMaxLength(300).IsRequired();
        b.Property(x => x.Summary).HasMaxLength(1000);
        b.Property(x => x.ProviderName).HasMaxLength(200).IsRequired();
        b.Property(x => x.ProviderOfferId).HasMaxLength(500);
        b.Property(x => x.Price).HasPrecision(14, 2);
        b.Property(x => x.Currency).HasMaxLength(3).IsFixedLength();
        b.Property(x => x.ConvertedPrice).HasPrecision(14, 2);
        b.Property(x => x.ExchangeRate).HasPrecision(18, 8);
        b.Property(x => x.ExchangeRateSource).HasMaxLength(100);
        b.Property(x => x.BookingUrl).HasMaxLength(2000);
        b.Property(x => x.DetailsJson).HasColumnType("jsonb").IsRequired();
        b.HasIndex(x => new { x.TripPlanId, x.SortOrder });
        b.HasIndex(x => x.ExpiresAtUtc);
    }
}
